INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"IN_ORDER_TO_INCREASE","Kako nam je cilj da proširimo našu dilersku mrežu i proširimo geografski doseg za našu distribuciju opreme za ugostiteljstvo, upućujemo poziv kompanijama koje su zainteresirane da postanu ovlašteni dileri za dugoročnu suradnju. Naše dilersko partnerstvo nudi atraktivne pogodnosti, uključujući strukturu popusta na više nivoa, fleksibilne opcije isporuke i plaćanja, sveobuhvatan paket transportnih i logističkih usluga, pristup tehničkim resursima i marketinški kolateral. Štaviše, dileri koji aktivno učestvuju u vladinim tenderskim akvizicijama imaju pravo na bonus programe podsticaja koji pružaju povećane nivoe popusta.");
