INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"IS_NOT_SALES_TYPES_HELP","Smjer prodaje za vaš račun nije naveden u našem računovodstvenom sistemu. Molimo kontaktirajte svog menadžera da dodijelite smjer prodaje vašoj suprotnoj strani.");
