INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"API_SUPERVISOR_ROLE_REQUIRED","Da biste generirali API ključ, morate imati račun s ulogom \"Nadzornik\". Ako vaša kompanija trenutno nema takav nalog, kontaktirajte svog menadžera. Alternativno, ako trebate samo da kreirate API ključ za buduću upotrebu, a vaša kompanija već ima nalog \"Supervisor\", kontaktirajte vlasnika naloga.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"API_API_KEY_WARNING","Generiranjem i korištenjem API ključa potvrđujete da se slažete s uvjetima korištenja. Svi zahtjevi napravljeni korištenjem vašeg API ključa bit će pripisani vama. Imajte na umu da će generiranje novog API ključa deaktivirati sve prethodno kreirane ključeve. Bit će potrebno ažurirati ključ u svim sistemima koji ga koriste.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"IS_NOT_ENTITY_FOR_PRICES","Naš računovodstveni sistem nema registrovano pravno lice. Za pristup cjenovnicima potrebno je aktivno pravno lice. Molimo kontaktirajte svog menadžera da popravi ovaj problem.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"LINKS_TO_PRICE_BACKWARD","Linkovi na cjenovnike s kompatibilnošću unatrag");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"ATTENTION_DIRECT_LINKS","\"Upozorenje! Direktne veze za preuzimanje sadrže vaš API ključ u nešifriranom obliku. Ne dijelite ove veze javno ili ni sa kim osim sa tehničkim stručnjacima koji su uključeni u integraciju kataloga. Dijeljenje vašeg ključa daje pristup procesiranju transakcija i pošiljaka u ime vašeg pravnog lica. \"");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"IF_FOR_SOME_REASON_NEW_LINKS","Ukoliko novi linkovi za preuzimanje cjenovnika iz bilo kojeg razloga nisu prikladni, možete koristiti linkove navedene u tabeli ispod. Format i sadržaj ovih starih cjenovnika u potpunosti su u skladu sa onim što vam je poznato. Međutim, imajte na umu da stari cjenovnici ne nude mogućnost odabira robe na osnovu dostupnosti, isključenje PDV-a iz cijene robe, niti uzimanje u obzir personaliziranih uslova ugovora vašeg pravnog lica. Ako želite da koristite ove nove funkcije, pogledajte opcije u nastavku.");
