INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICE_TO_GET_DIRECT_LINK","Morate imati nalog sa ulogom „Supervizor“ da biste dobili direktne veze za preuzimanje cjenovnika. Ako nemate račun s ovom ulogom, kontaktirajte svog menadžera. Ukoliko Vam je potrebno samo da dobijete direktne linkove za njegovo dalje korišćenje, a Vaša kompanija ima nalog „Supervizor“, obratite se njegovom vlasniku.");
