INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_DESC"," Opis proizvodaponuda.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_PURCHASE_TYPE","Vrsta kupovine. Može imati vrijednosti:<br/> <ul> <li><b>'na zalihi'</b> - artikal je na zalihama barem u jednom od odabranih skladišta</li> <li><b>' na putu'</b> - artikal je u najbližoj isporuci u skladište u Moskvi</li> <li><b>'na zahtjev'</b> - roba se može donijeti u skladište u Moskvi na zahtjev. <b>Posebni uslovi plaćanja</b> - provjerite kod menadžera.</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_DELIVERY_TIME","Rok isporuke artikala na zahtjev u skladište u Moskvi se mjeri u danima i može varirati u određenim vrijednostima:<br> <ul> <li><b>broj (dana)</b></li> <li> <b>'više nije dostupno'</b> - isporuke su zaustavljene,</li> <li><b>'provjerite'</b> - provjerite kod menadžera,</li> <li>prazan red - ako rok isporuke nije definisan</li> </ul>");
