INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_MODEL","Model i važni parametri (na primjer, indeks modela, karakteristike modifikacije, itd.). Uzima vrijednost <b>nedefinirano</b> ako nije postavljena.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_SALES_NOTES","Element se koristi za prikaz informacija o:<br> <ul> <li>potrebi da se kod menadžera odredi rok isporuke;</li> <li>o prekidu kupovine artikla (ne isporučujemo stavka više).</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_DELIVERY_OPTIONS","Vrijeme isporuke <b>za artikle na zahtjev</b> u skladište u Moskvi. Vrijednost se šalje u atributu <b>days</b>. Prikazuje se samo ako je isporuka dostupna za artikl.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_WEIGHT","Element je dizajniran da odredi težinu predmeta. <b>Težina je u kilogramima uključujući pakovanje</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_DIMENSIONS","Element je dizajniran da specificira dimenzije artikla (dužina, širina, visina) u pakovanju. <b>Dimenzije su u centimetrima</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_DELIVERY","Dostupnost dostave. Prihvaća vrijednosti:<br> <ul> <li><b>false</b> — više ne šaljemo artikl ili trebate provjeriti vrijeme isporuke kod menadžera;</li> <li><b >tačno</b> — artikl može biti isporučen;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_PICKUP","Dostupnost za preuzimanje. Prihvaća vrijednosti:<br> <ul> <li><b>false</b> — više ne isporučujemo artikl i nema ga na zalihama;</li> <li><b>tačno</b> > — artikal je na lageru ili je moguća dostava na upit, možete rezervirati odabrani artikl i preuzeti ga sami;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"NON_STANDART","Nestandardni elementi");
