INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"PRICES_D_PRICE_CSV","Trenutna cijena artikla je prikazana u rubljama. Ovisno o odabranom cjeniku, cijena može biti ili maloprodajna ili dilerska cijena.");
