INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_BRANDMANAGER_TEXT","Imate pristup odjeljku upita za vaš brend. Konkretno za privatne robne marke, možete upravljati katalogom vašeg brenda na imex.gkrp.local, potvrditi prava preuzimanja datoteka i obavijestiti glavnog menadžera o potvrdama korisničkog portala na vašoj stranici. Također možete pogledati cijene za sve cjenovnike, uključujući i one za EU.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_ZIPMANAGER_TEXT","Imate pristup za pregled transakcija i povezanih informacija vezanih za prodaju rezervnih dijelova, uključujući sve reklamacije, kao i pristup za pregled svih cjenovnika.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_QUALITYMANAGER_TEXT","Imate pristup svim transakcijama, zahtjevima i upitima za reklamacije.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_SENIORZIPMANAGER_TEXT","U mogućnosti ste pregledati transakcije i povezane informacije u vezi s prodajom rezervnih dijelova, rješavati sve reklamacije, pristupiti svim cjenovnicima, upravljati zaposlenima u svom odjelu, slati obavještenja glavnom menadžeru o potvrdama korisnika na portalu (ako je korisnik vaš kupac), i registruje transakcije u ime druge strane u smeru prodaje rezervnih delova.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_SENIORQUALITYMANAGER_TEXT","Imate pristup svim transakcijama, reklamacijama i upitima (dodacima) vezanim za reklamacije. Takođe, možete uređivati zaposlene unutar vašeg odjela.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_SENIORCOMPLAINTMANAGER_TEXT","Imate pristup svim transakcijama, reklamacijama i upitima (dodacima) vezanim za reklamacije. Takođe, možete uređivati zaposlene unutar vašeg odjela.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_COMPLAINTMANAGER_TEXT","Imate pristup zahtjevima u kojima ste raspoređeni kao glavni inženjer.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,9,"GROUP_HEADBRANDMANAGER_TEXT","Imate pristup odjeljku upita za vaš brend. Konkretno za privatne robne marke, možete upravljati katalogom vašeg brenda na imex.gkrp.local, potvrditi prava preuzimanja datoteka i obavijestiti glavnog menadžera o potvrdama korisničkog portala na vašoj stranici. Također možete pogledati cijene za sve cjenovnike, uključujući i one za EU.");
